import java.util.Arrays;

public class SortingBasics {

    // ===== 快速排序（Lomuto 分区，选末尾为 pivot） =====
    public static void quickSort(int[] arr, int lo, int hi) {
        if (lo < hi) {
            int p = partition(arr, lo, hi);
            quickSort(arr, lo, p - 1);   // 左半部分：≤ pivot
            quickSort(arr, p + 1, hi);   // 右半部分：> pivot
        }
    }

    private static int partition(int[] arr, int lo, int hi) {
        int pivot = arr[hi];            // 选末尾元素为基准
        int i = lo;                     // i 指向「≤ pivot」区间的下一个位置
        for (int j = lo; j < hi; j++) {
            if (arr[j] <= pivot) {      // 遇到 ≤ pivot 的元素就归入左区间
                swap(arr, i, j);
                i++;
            }
        }
        swap(arr, i, hi);               // 把 pivot 放到最终位置
        return i;
    }

    // ===== 归并排序 =====
    public static void mergeSort(int[] arr, int left, int right) {
        if (left < right) {
            int mid = left + (right - left) / 2;  // 防整数溢出
            mergeSort(arr, left, mid);
            mergeSort(arr, mid + 1, right);
            merge(arr, left, mid, right);
        }
    }

    private static void merge(int[] arr, int left, int mid, int right) {
        int[] tmp = new int[right - left + 1];    // 辅助数组
        int i = left, j = mid + 1, k = 0;
        while (i <= mid && j <= right) {
            // <= 保证稳定性：相等时优先取左半部分
            if (arr[i] <= arr[j]) {
                tmp[k++] = arr[i++];
            } else {
                tmp[k++] = arr[j++];
            }
        }
        while (i <= mid)  tmp[k++] = arr[i++];
        while (j <= right) tmp[k++] = arr[j++];
        System.arraycopy(tmp, 0, arr, left, tmp.length);
    }

    private static void swap(int[] arr, int a, int b) {
        if (a == b) return;
        int t = arr[a]; arr[a] = arr[b]; arr[b] = t;
    }

    // ===== 演示 =====
    public static void main(String[] args) {
        int[] a1 = {5, 3, 8, 4, 2, 7, 1, 6};
        quickSort(a1, 0, a1.length - 1);
        System.out.println("QuickSort: " + Arrays.toString(a1));

        int[] a2 = {5, 3, 8, 4, 2, 7, 1, 6};
        mergeSort(a2, 0, a2.length - 1);
        System.out.println("MergeSort: " + Arrays.toString(a2));

        // 基本有序数据：插入排序 O(n) 优势场景
        int[] a3 = {1, 2, 3, 5, 4, 6, 7, 8};
        insertionSort(a3);
        System.out.println("InsertionSort (nearly sorted): " + Arrays.toString(a3));
    }

    // 插入排序（小规模 / 基本有序最优）
    public static void insertionSort(int[] arr) {
        for (int i = 1; i < arr.length; i++) {
            int key = arr[i];
            int j = i - 1;
            while (j >= 0 && arr[j] > key) {
                arr[j + 1] = arr[j];
                j--;
            }
            arr[j + 1] = key;
        }
    }
}
